inline ::flatbuffers::Offset<FillEvent> CreateFillEvent(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    const aegis::mx::contracts::v1::SchemaVersion *schema_version = nullptr,
    const aegis::mx::contracts::v1::GlobalEventId *global_event_id = nullptr,
    const aegis::mx::contracts::v1::OrderId *order_id = nullptr,
    const aegis::mx::contracts::v1::IntentId *intent_id = nullptr,
    const aegis::mx::contracts::v1::SessionId *session_id = nullptr,
    const aegis::mx::contracts::v1::VenueId *venue_id = nullptr,
    const aegis::mx::contracts::v1::InstrumentId *instrument_id = nullptr,
    uint64_t venue_trade_id = 0,
    aegis::mx::contracts::v1::PriceUnit price_unit = aegis::mx::contracts::v1::PriceUnit::UNKNOWN,
    int64_t fill_price_ticks = 0,
    aegis::mx::contracts::v1::QuantityUnit quantity_unit = aegis::mx::contracts::v1::QuantityUnit::UNKNOWN,
    uint64_t fill_quantity_units = 0,
    aegis::mx::contracts::v1::CurrencyUnit currency_unit = aegis::mx::contracts::v1::CurrencyUnit::UNKNOWN,
    int64_t fee_currency_nanos = 0,
    const aegis::mx::contracts::v1::ExchangeEventTimeNs *exchange_event_time = nullptr,
    const aegis::mx::contracts::v1::NicReceiveTimeNs *nic_receive_time = nullptr,
    const aegis::mx::contracts::v1::ProcessMonotonicTimeNs *process_monotonic_time = nullptr) {
  FillEventBuilder builder_(_fbb);
  builder_.add_fee_currency_nanos(fee_currency_nanos);
  builder_.add_fill_quantity_units(fill_quantity_units);
  builder_.add_fill_price_ticks(fill_price_ticks);
  builder_.add_venue_trade_id(venue_trade_id);
  builder_.add_process_monotonic_time(process_monotonic_time);
  builder_.add_nic_receive_time(nic_receive_time);
  builder_.add_exchange_event_time(exchange_event_time);
  builder_.add_instrument_id(instrument_id);
  builder_.add_venue_id(venue_id);
  builder_.add_session_id(session_id);
  builder_.add_intent_id(intent_id);
  builder_.add_order_id(order_id);
  builder_.add_global_event_id(global_event_id);
  builder_.add_schema_version(schema_version);
  builder_.add_currency_unit(currency_unit);
  builder_.add_quantity_unit(quantity_unit);
  builder_.add_price_unit(price_unit);
  return builder_.Finish();
}

