template <bool B>
inline bool VerifyMarketPayload(::flatbuffers::VerifierTemplate<B> &verifier, const void *obj, MarketPayload type) {
  switch (type) {
    case MarketPayload::NONE: {
      return true;
    }
    case MarketPayload::BookUpdate: {
      auto ptr = reinterpret_cast<const aegis::mx::contracts::v1::BookUpdate *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MarketPayload::TradeEvent: {
      auto ptr = reinterpret_cast<const aegis::mx::contracts::v1::TradeEvent *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MarketPayload::QuoteEvent: {
      auto ptr = reinterpret_cast<const aegis::mx::contracts::v1::QuoteEvent *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MarketPayload::AuctionImbalance: {
      auto ptr = reinterpret_cast<const aegis::mx::contracts::v1::AuctionImbalance *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MarketPayload::TradingStatus: {
      auto ptr = reinterpret_cast<const aegis::mx::contracts::v1::TradingStatus *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

template <bool B>
inline bool VerifyMarketPayloadVector(::flatbuffers::VerifierTemplate<B> &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<MarketPayload> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyMarketPayload(
        verifier,  values->Get(i), types->GetEnum<MarketPayload>(i))) {
      return false;
    }
  }
  return true;
}

